+        let real = handshaker.cell_for(&peer("10.0.0.1"));
+        assert!(Arc::ptr_eq(&real, &handshaker.cell_for(&peer("10.0.0.1"))));
+        let other_host = handshaker.cell_for(&peer("10.6.6.6"));
+        assert!(
