+            PeerTlsConfig {
+                ca_file: Some("ca.pem".to_string()),
+                identity: Some(("server.pem".to_string(), "server.pem".to_string())),
+            }
+        );
+        let split = TlsConfig {
+            key_file: Some("server.key".to_string()),
+            ca_certs: None,
+            ..combined
+        };
+        assert_eq!(
